"""Render a clearly scoped research snapshot from completed aggregate reports."""
from pathlib import Path
from html import escape
import json
import pandas as pd
ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'src/volrisk/workspace.html';html=path.read_text()
coverage=json.loads((ROOT/'results/FULL_COHORT_AUDIT_V2.json').read_text())
scores=pd.read_csv(ROOT/'results/FULL_TRAINING_V1.csv').set_index('model')
portfolio=json.loads((ROOT/'results/FULL_PORTFOLIO_AUDIT_V1.json').read_text())
rows=''.join(f'<tr><td>{label}</td><td>{100*scores.loc[m,"mae"]:.2f}</td><td>{scores.loc[m,"qlike"]:.3f}</td></tr>' for m,label in [('Ridge60_calibrated','Ridge · calibrated'),('LSTM60_calibrated','LSTM · calibrated'),('Timestral5M_calibrated','Timestral 5M · calibrated')])
policy=''
for r in portfolio['comparisons']:
    if r['model']=='LSTM60_calibrated':
        basket='11-sector basket' if r['basket']=='Held-sector basket' else 'Technology basket'
        baseline='Fixed validation equity' if r['benchmark']=='fixed_validation' else 'Historical risk'
        policy+=f'<tr><td>{basket}</td><td>{baseline}</td><td>{100*r["risk_error_difference"]:+.3f}</td><td>{100*r["return_difference"]:+.2f}</td><td>{100*r["equity_difference"]:+.2f}</td></tr>'
block=f'''<section class="glass researchSnapshot" id="latestResearch"><div class="sectionhead"><div><div class="eyebrow">Latest completed research</div><h2>From forecast accuracy to decision value</h2></div><span class="chip">Exploratory · 2024–2025</span></div><p>The full research panel and the interactive replay have different scopes. The Portfolio Lab tab uses its saved 30-stock preliminary inputs. The results below come from the completed full-cohort experiments.</p><div class="overviewMetrics"><div><span>Retained price histories</span><strong>{coverage['retained_raw_histories']}</strong><small>500 reconstructed reference-date candidates</small></div><div><span>Daily company observations</span><strong>{coverage['raw_company_date_rows_retained']:,}</strong><small>Unique company-date rows · through 2025</small></div><div><span>Held-company evaluation</span><strong>97 firms</strong><small>46,657 common forecast origins</small></div><div><span>Final time holdout</span><strong>2026 sealed</strong><small>Not downloaded or scored</small></div></div><h3>Does the model forecast better?</h3><p>All three rows use the same evaluation origins. Calibration is fitted only on non-held validation companies. LSTM has a lower average QLIKE than Ridge; both paired 20/60-date intervals for the difference cross zero.</p><div class="scroll"><table><thead><tr><th>Forecast procedure</th><th>MAE (volatility pp)</th><th>QLIKE ↓</th></tr></thead><tbody>{rows}</tbody></table></div><p class="hint">Timestral is a recent pretrained Transformer comparator. Its context and point summary differ from the supervised models, and pretraining overlap is unverified. These rows do not establish architecture-wide superiority.</p><h3>Does it improve the portfolio decision?</h3><p>LSTM improves risk-target tracking relative to the historical-risk rule in these two baskets, alongside lower equity exposure and lower returns. Against validation-fixed equity, the error differences are close to zero and both interval lengths cross zero. A reliable dynamic-policy advantage is not established.</p><div class="scroll"><table><thead><tr><th>Basket</th><th>Compared with</th><th>Risk-error Δ (pp)</th><th>Net-return Δ (pp)</th><th>Equity Δ (pp)</th></tr></thead><tbody>{policy}</tbody></table></div><p class="hint">Calibrated LSTM · 10% target · 10 bps costs · zero cash yield. Negative risk-error differences favor dynamic exposure. Fixed controls use validation planned exposure, not matched realized test risk. The full report retains all 384 strategy records and unfavorable outcomes.</p><div class="researchLinks"><a href="https://github.com/yhan0427/STAT3108Final-Project/blob/main/results/FULL_TRAINING_V1.md" target="_blank" rel="noopener noreferrer">Forecast study ↗</a><a href="https://github.com/yhan0427/STAT3108Final-Project/blob/main/results/FULL_PORTFOLIO_V1.md" target="_blank" rel="noopener noreferrer">Decision study ↗</a><a href="https://github.com/yhan0427/STAT3108Final-Project/blob/main/results/FULL_COHORT_COVERAGE_V2.md" target="_blank" rel="noopener noreferrer">Data coverage ↗</a></div><p class="hint">Fixed 2025-12-31 cohort reconstructed with explicit source corrections; it is not historical index membership at every date. Missing histories and survivor selection remain limitations. This snapshot is not included in the assistant's scenario evidence; the assistant continues to use the applied Portfolio Lab selection.</p></section>'''
if '<section class="glass researchSnapshot" id="latestResearch">' in html:
    start=html.index('<section class="glass researchSnapshot" id="latestResearch">');end=html.index('</section>',start)+len('</section>');html=html[:start]+block+html[end:]
else:
    anchor='<div class="aboutGrid">';pos=html.index(anchor);html=html[:pos]+block+html[pos:]
html=html.replace('These are existing baselines; a recent time-series method has not yet been added or validated.','The separate full-cohort research now includes Timestral 5M; the interactive replay retains its preliminary V2 inputs.')
html=html.replace("Audit a recent method's code and pretraining overlap, fix a new evaluation protocol, test new observations and assess sensitivity to costs, correlation windows and cash yield.","Finalize the evaluation protocol, resolve remaining identity/coverage limitations and review pretraining overlap before opening the sealed 2026 time holdout.")
html=html.replace('Thirty fixed US non-financial large-cap stocks, adjusted daily prices and existing SEC-informed forecasting experiments. This survivor-selected sample is not historical S&amp;P 500 membership.','Interactive replay: thirty fixed non-financial large caps. Full research: 491 retained histories from 500 reconstructed reference-date issuers, including financial firms in market-only experiments. Neither panel reconstructs historical index membership at every date.')
path.write_text(html)
